package dev.pedro.learning.ecommerce.notification.provider;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;@Path("/admin/email-provider")@Produces(MediaType.APPLICATION_JSON)public class EmailProviderAdminResource{private final FakeEmailProvider provider;public EmailProviderAdminResource(FakeEmailProvider provider){this.provider=provider;}@PUT @Path("/mode/{mode}")public EmailProviderStats mode(@PathParam("mode")EmailProviderMode mode){provider.mode(mode);return stats();}@PUT @Path("/fail-first/{count}")public EmailProviderStats failFirst(@PathParam("count")int count){provider.failFirstN(count);provider.mode(EmailProviderMode.FAIL_FIRST_N_ATTEMPTS);return stats();}@PUT @Path("/delay/{millis}")public EmailProviderStats delay(@PathParam("millis")long millis){provider.delayMs(millis);return stats();}@PUT @Path("/reset")public EmailProviderStats reset(){provider.reset();return stats();}@GET @Path("/stats")public EmailProviderStats stats(){return new EmailProviderStats(provider.mode(),provider.calls(),provider.successes(),provider.failures(),provider.failFirstN(),provider.delayMs());}}